def factorial(n):
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def fibonacci(n: int) -> int:
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return 0
    if n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

import re

def is_palindrome(text: str) -> bool:
    if text is None:
        return True
    cleaned = re.sub(r'[^0-9a-zA-Z]+', '', text).lower()
    return cleaned == cleaned[::-1]

def clamp(value, lower, upper):
    """
    将 value 限制在闭区间 [lower, upper]。
    若 lower > upper，抛出 ValueError。
    """
    if lower > upper:
        raise ValueError("lower must be less than or equal to upper")
    if value < lower:
        return lower
    if value > upper:
        return upper
    return value

def count_vowels(text):
    vowels = {'a', 'e', 'i', 'o', 'u'}
    count = 0
    for ch in text.lower():
        if ch in vowels:
            count += 1
    return count

from typing import Iterable, List, TypeVar, Set

T = TypeVar("T")

def deduplicate(items: Iterable[T]) -> List[T]:
    seen: Set[T] = set()
    result: List[T] = []
    for x in items:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result
